def getCentroid(self, stats, sid):
    """Extracts 3D spatial center coordinates for distance matrix calculations."""
    for k in stats.keys():
        if len(k) == 2 and k[0] == sid and 'centroid' in k[1].lower(): return stats[k]
    return (0.0, 0.0, 0.0)

